static void testAutomationWrite(const File& root,Assets& assets){
    using W=AutomationWrite;
    {
        W gated;auto old=gated.entryToken();expect(gated.begin({0,7,4,8,9,W::Mode::touch},true),"deferred capture arms without exposing a partially submitted transport start");
        gated.control(.8f,true);gated.block(0,false,8,old);gated.block(0,false,8,gated.entryToken());expect(gated.phase()==W::Phase::armed&&!gated.result(),"callbacks before activation cannot cancel capture using old position, stopped transport or revision");
        double transportStart=-1;expect(!gated.transportStart(gated.entryToken(),9,transportStart)&&transportStart==-1,"deferred transport cannot start before activation");
        auto beforeStart=gated.entryToken();gated.activate();gated.block(0,false,8,beforeStart);expect(gated.phase()==W::Phase::armed,"a callback entered before transport publication cannot start or cancel the newly activated pass");
        expect(!gated.transportStart(beforeStart,9,transportStart)&&!gated.transportStart(gated.entryToken(),8,transportStart)&&gated.transportStart(gated.entryToken(),9,transportStart)&&transportStart==4,"only a fresh callback with the committed project can restore the exact capture start after an older callback consumed the seek");
        gated.block(4,true,9,gated.entryToken());expect(gated.phase()==W::Phase::running&&gated.overriding()&&gated.value()==.8f,"the next callback starts capture at the committed timeline without losing an early gesture");
        gated.tick(4.5,true);gated.interrupt(4.5,true);expect(gated.result()&&gated.result()->end==W::End::stopped&&gated.result()->segmentCount==1,"activated capture still finalizes a real Stop as a reviewable pass");
        auto ended=gated.entryToken();expect(gated.begin({0,7,4,8,10,W::Mode::write,.4f}),"ordinary capture begin remains supported for engine and offline clients");gated.block(0,false,9,ended);expect(gated.phase()==W::Phase::armed,"an old callback cannot cancel a replacement pass either");gated.block(4,false,10,gated.entryToken());expect(gated.result()&&gated.result()->end==W::End::stopped,"a Stop after publication still ends an unstarted pass");
    }
    W recorder;expect(!recorder.begin({126,0,0,2,0,W::Mode::touch})&&!recorder.begin({0,16,0,2,0,W::Mode::touch})&&!recorder.begin({0,0,0,601,0,W::Mode::touch}),"write plans reject unknown targets, destinations and oversized ranges");
    expect(recorder.begin({0,7,4,8,9,W::Mode::touch}),"Touch pass arms a bounded selected range");recorder.block(4,true,9);recorder.control(.8f,true);recorder.block(4.25,true,9);recorder.tick(4.5,true);recorder.control(.4f,true);recorder.block(4.5,true,9);recorder.control(.4f,false);recorder.block(5,true,9);expect(!recorder.overriding(),"Touch immediately releases its override back to existing automation");recorder.control(.6f,true);recorder.block(6,true,9);recorder.tick(8,true);auto take=recorder.result();
    expect(take&&take->end==W::End::complete&&take->segmentCount==2&&take->pointCount==5&&take->segments[0].start==4.25&&take->segments[0].end==5&&take->segments[1].end==8,"Touch records separate held overlay intervals and exact clip endpoint");
    expect(recorder.begin({118,-1,0,2,3,W::Mode::latch}),"Master Latch pass can replace a reviewed result");recorder.control(.75f,true);recorder.block(0,true,3);recorder.control(.75f,false);recorder.block(1,true,3);expect(recorder.overriding()&&recorder.value()==.75f,"Latch keeps the final value after mouse release");recorder.interrupt(1.25,true);take=recorder.result();expect(take&&take->end==W::End::stopped&&take->segments[0].end==1.25,"Stop finalizes Latch before a rewind destroys its timeline position");
    recorder.begin({0,7,0,2,0,W::Mode::touch});recorder.block(0,true,0);recorder.tick(2,true);expect(recorder.result()&&recorder.result()->segmentCount==0,"untouched passes remain empty without baseline rewrite");
    recorder.begin({0,7,0,2,0,W::Mode::touch});recorder.control(.4f,true);recorder.block(0,true,0);recorder.block(.2,true,1);expect(recorder.result()&&recorder.result()->end==W::End::changed,"revision change invalidates capture instead of attaching to stale data");
    recorder.begin({0,7,0,2,0,W::Mode::touch});recorder.control(.4f,true);recorder.block(0,true,0);recorder.interrupt(.2,false);expect(recorder.result()&&recorder.result()->end==W::End::discontinuity,"seek invalidates a pass atomically");
    recorder.begin({0,7,0,2,0,W::Mode::touch});recorder.control(.4f,true);recorder.block(0,true,0);recorder.tick(.8,true);recorder.tick(.1,true);expect(recorder.result()&&recorder.result()->end==W::End::discontinuity,"unexpected loop wrap rejects ambiguous recorded timestamps");
    recorder.begin({0,7,0,2,0,W::Mode::touch});recorder.cancel();recorder.block(0,true,0);expect(recorder.result()&&recorder.result()->end==W::End::cancelled,"cancel is acknowledged by the callback without UI ownership races");
    recorder.begin({0,7,0,10,0,W::Mode::latch});recorder.control(.4f,true);recorder.block(0,true,0);for(int i=1;i<300&&recorder.phase()!=W::Phase::ready;++i){recorder.control(i%2?.2f:.8f,true);recorder.block(i*.01,true,0);}expect(recorder.result()&&recorder.result()->end==W::End::capacity&&recorder.result()->pointCount<=256,"point overflow stops safely without allocating or silently truncating an applicable take");
    recorder.begin({0,7,0,10,0,W::Mode::touch});for(int i=0;i<17&&recorder.phase()!=W::Phase::ready;++i){recorder.control(.5f,true);recorder.block(i*.1,true,0);recorder.control(.5f,false);recorder.block(i*.1+.05,true,0);}expect(recorder.result()&&recorder.result()->end==W::End::capacity&&recorder.result()->segmentCount==16,"gesture overflow retains bounded capture storage and invalidates the pass");
    recorder.begin({0,7,0,2,0,W::Mode::touch});recorder.control(.5f,true);recorder.block(0,true,0);recorder.control(.5f,false);recorder.block(0,true,0);recorder.interrupt(0,true);expect(recorder.result()&&recorder.result()->segmentCount==0&&recorder.result()->pointCount==0,"zero-duration clicks do not produce invalid one-point clips");
    recorder.begin({0,7,0,2,0,W::Mode::latch});recorder.control(.5f,true);recorder.block(0,true,0);recorder.control(std::numeric_limits<float>::quiet_NaN(),true);recorder.block(.5,true,0);expect(recorder.value()==.5f,"nonfinite live write values are ignored");recorder.interrupt(1,true);
    expect(!recorder.begin({0,7,0,2,0,W::Mode::write,std::numeric_limits<float>::quiet_NaN()})&&!recorder.begin({0,7,0,2,0,W::Mode::write,1.01f})&&!recorder.begin({0,7,0,2,0,(W::Mode)77,.5f}),"invalid Write initial values and modes reject before arming");
    expect(recorder.begin({0,7,4,8,9,W::Mode::write,.35f}),"Write arms with an explicit initial effective value");recorder.block(4,true,9);
    expect(recorder.overriding()&&recorder.value()==.35f,"Write starts immediately without a touched gesture");recorder.control(.65f,true);recorder.block(5,true,9);recorder.control(.65f,false);recorder.block(6,true,9);recorder.tick(8,true);take=recorder.result();
    expect(take&&take->segmentCount==1&&take->pointCount==3&&take->segments[0].start==4&&take->segments[0].end==8&&take->points[0].value==.35f&&take->points[1].beat==5&&take->points[2].value==.65f,"Write captures one complete held range and retains changes after release");
    recorder.begin({0,7,0,2,0,W::Mode::write,.42f});recorder.block(0,true,0);recorder.tick(2,true);take=recorder.result();expect(take&&take->segmentCount==1&&take->pointCount==2&&take->points[0].value==.42f&&take->points[1].value==.42f,"untouched Write intentionally records the initial held value across its whole range");
    recorder.begin({0,7,0,2,0,W::Mode::write,.42f});recorder.block(0,true,0);recorder.interrupt(.75,true);expect(recorder.result()&&recorder.result()->segments[0].end==.75&&recorder.result()->end==W::End::stopped,"Write Stop retains only the performed prefix");
    recorder.begin({0,7,0,2,0,W::Mode::write,.42f});recorder.block(0,true,0);recorder.cancel();recorder.block(.2,true,0);expect(recorder.result()&&recorder.result()->end==W::End::cancelled,"Write cancellation invalidates its full-range take");
    // Render a real captured volume pass, then replay the exact overlay data with
    // another callback size and through the normal offline exporter.
    auto project=emptyProject();project.bpm=120;project.songMode=true;project.loop=false;project.delayReturn=0;project.tracks[7].instrument=Instrument::analog;project.patterns[0].lanes[7]={{0,4,48,.8f}};Clip source;source.track=7;source.length=2;Clip curve;curve.track=7;curve.automationTrack=7;curve.automationTarget=0;curve.length=2;curve.points={{0,.2f,false,AutomationCurve::smooth,.4f},{2,.7f}};project.clips={source,curve};
    auto engine=makeEngine(project,assets,root);engine->automationWrite.begin({0,7,0,2,0,W::Mode::touch});AudioBuffer<float> live(2,48000);
    for(int frame=0;frame<48000;frame+=256){if(frame==0)engine->automationWrite.control(.8f,true);if(frame==8192)engine->automationWrite.control(.4f,true);if(frame==16384)engine->automationWrite.control(.4f,false);engine->render(live.getWritePointer(0,frame),live.getWritePointer(1,frame),jmin(256,48000-frame));}
    take=engine->automationWrite.result();expect(take&&take->end==W::End::complete&&take->segmentCount==1,"engine stamps gestures on consumed callback boundaries and finishes at the exact range end");
    if(take)for(int i=0;i<take->segmentCount;++i){const auto& s=take->segments[(size_t)i];Clip overlay;overlay.track=7;overlay.automationTarget=0;overlay.automationTrack=7;overlay.beat=s.start;overlay.length=s.end-s.start;for(int n=0;n<s.count;++n){const auto& v=take->points[(size_t)(s.first+n)];overlay.points.push_back({v.beat-s.start,v.value,true});}project.clips.push_back(overlay);}
    auto replay=render(project,assets,root,48000,127);double error=0;for(int c=0;c<2;++c)for(int n=0;n<48000;++n)error=jmax(error,(double)std::abs(live.getSample(c,n)-replay.getSample(c,n)));expect(error<1e-6,"recorded Touch overlay reproduces live audio including exact nonlinear underlying curve return");
    auto path=root.getChildFile("automation-write.pulse");Project reopened;expect(saveProject(project,path).wasOk()&&loadProject(path,reopened).wasOk()&&reopened.clips.back().points==project.clips.back().points&&reopened.clips[1].points==curve.points,"recorded overlays and untouched original shapes save/reopen in the existing schema");
    RenderSettings settings;settings.bits=32;settings.endBeat=2;settings.tailSeconds=0;auto wav=root.getChildFile("automation-write.wav");expect(renderAudio(project,assets,root,wav,settings).wasOk(),"recorded automation exports through the common offline renderer");String issue;auto sample=assets.load(wav,issue);error=0;if(sample&&sample->audio.getNumSamples()==48000){for(int c=0;c<2;++c)for(int n=0;n<48000;++n)error=jmax(error,(double)std::abs(sample->audio.getSample(c,n)-live.getSample(c,n)));}else error=1;expect(error<1e-6,"offline recorded automation matches the live capture audition");
    auto looped=project;looped.loop=true;auto loopEngine=makeEngine(looped,assets,root);loopEngine->automationWrite.begin({0,7,0,2,0,W::Mode::latch});loopEngine->automationWrite.control(.6f,true);for(int i=0;i<188;++i){float scratch[256];loopEngine->render(scratch,nullptr,256);}expect(loopEngine->automationWrite.result()&&loopEngine->automationWrite.result()->end==W::End::complete,"pass end wins over a loop wrap at the same sample");
    auto stopped=makeEngine(project,assets,root);stopped->automationWrite.begin({0,7,0,2,0,W::Mode::latch});stopped->automationWrite.control(.6f,true);float scratch[256];stopped->render(scratch,nullptr,256);double at=stopped->position.load();stopped->stop();stopped->render(scratch,nullptr,256);expect(stopped->automationWrite.result()&&stopped->automationWrite.result()->end==W::End::stopped&&std::abs(stopped->automationWrite.result()->segments[0].end-at)<1e-9&&stopped->position.load()==0,"native Stop records its final endpoint before rewinding transport");
    for(auto mode:{W::Mode::touch,W::Mode::write})for(auto [target,destination]:std::array<std::pair<int,int>,9>{{{59,7},{10,7},{108,-1},{116,7},{118,-1},{119,-1},{120,-1},{121,7},{0,9}}}){
        auto song=emptyProject();song.tracks.resize(10);song.patterns[0].lanes.resize(10);song.songMode=true;song.loop=false;song.bpm=120;song.delayReturn=.5f;song.tracks[7].instrument=Instrument::analog;song.tracks[7].send=.4f;song.tracks[7].mixer.distortion.enabled=true;song.tracks[7].mixer.distortion.mix=.7f;song.tracks[7].mixer.distortion.drive=12;song.tracks[9].isBus=true;song.tracks[7].mixer.output=9;song.patterns[0].lanes[7]={{0,4,48,.8f}};Clip notes;notes.track=7;notes.length=2;Clip base;base.track=7;base.automationTrack=destination;base.automationTarget=target;base.length=2;base.points={{0,.1f,true},{2,.1f,true}};song.clips={notes,base};
        auto captured=makeEngine(song,assets,root);expect(captured->automationWrite.begin({target,destination,0,2,0,mode,.1f}),"Touch/Write synth, effect, selector, Master, mute and routed-bus targets arm through the same writer");AudioBuffer<float> audition(2,48000);
        for(int frame=0;frame<48000;frame+=256){if(frame==0&&mode==W::Mode::touch)captured->automationWrite.control(.9f,true);if(frame==8192)captured->automationWrite.control(.4f,true);if(frame==16384)captured->automationWrite.control(.4f,false);captured->render(audition.getWritePointer(0,frame),audition.getWritePointer(1,frame),jmin(256,48000-frame));}
        const auto* recorded=captured->automationWrite.result();expect(recorded&&recorded->segmentCount==1&&recorded->end==W::End::complete,"parameter-family capture completes within fixed storage");
        if(recorded){const auto& segment=recorded->segments[0];Clip overlay;overlay.track=7;overlay.automationTrack=destination;overlay.automationTarget=target;overlay.beat=segment.start;overlay.length=segment.end-segment.start;for(int n=0;n<segment.count;++n){const auto& point=recorded->points[(size_t)(segment.first+n)];overlay.points.push_back({point.beat-segment.start,point.value,true});}song.clips.push_back(overlay);}
        auto replayed=render(song,assets,root,48000,127);double worst=0;for(int channel=0;channel<2;++channel)for(int frame=0;frame<48000;++frame)worst=jmax(worst,(double)std::abs(replayed.getSample(channel,frame)-audition.getSample(channel,frame)));expect(worst<1e-6,"captured parameter families replay identical actual audio across callback sizes");
    }

}
